guide_body = heading('Understand the diagram.<br>Change the actual design.', 'A field guide to the diagrams and processes in the example collection. Each lesson links to its converted source and all three new utilities.', 'Field guide') + '<div class="grid">' + card('quick-start.html', 'New to DDN?', 'Write a simple ERD, add fields and choose a connection type.') + card('language.html', 'Language guide', 'Indentation, tables, notes, shared definitions, defaults and lifecycle.') + card('ddn-ai-reference.txt', 'DDN for AI assistants', 'Download one self-contained text reference. Attach it with your diagram description to generate the new DDN dialect.') + card('../gallery/index.html', 'Visual gallery', 'Browse examples by profile, process or presentation variation.') + '</div><div class="search-controls"><label class="grow" for="lesson-search">Search the field guide<input type="search" id="lesson-search" data-filter="lesson-list" data-count="lesson-count" placeholder="Try schema, sequence, planning or chart"></label></div><p id="lesson-count" class="count" aria-live="polite">160 lessons</p><div id="lesson-list">'
for category, items in groups.items():
    guide_body += f'<section class="lesson-category" data-filter-section><h2>{esc(category)}</h2><ul>'
    for lesson in items:
        guide_body += f'<li data-search="{esc(lesson["title"] + " " + category + " " + " ".join(lesson.get("tags", [])))}"><a href="lessons/{esc(lesson["id"])}.html">{esc(lesson["title"])}<small>{esc(lesson.get("profile") or "DDN")}</small></a></li>'
    guide_body += '</ul></section>'
guide_body += '</div>'
page('guide/index.html', 'Field guide', guide_body, active='Guide')
for index, lesson in enumerate(lessons):
    body = '<p class="breadcrumbs"><a href="../index.html">Field guide</a> / ' + esc(lesson['category']) + '</p>' + heading(esc(lesson['title']), esc(lesson.get('what', '')), lesson['category'])
    if lesson.get('profile'):
        body += f'<div class="fact-row"><a class="pill" href="../../reference/profiles/{slug(lesson["profile"])}.html">{esc(lesson["profile"])}</a><span class="pill">New DDN source</span></div>'
    body += actions(lesson['entry'], lesson['view'], '../../')
    body += '<section class="two-column"><div><h2>Why use it?</h2><p>' + esc(lesson.get('why', '')) + '</p></div><div><h2>When it helps</h2><p>' + esc(lesson.get('when', '')) + '</p></div></section>'
    for key, title in [('read','How to read it'),('inputs','What you need'),('pitfalls','Things to check')]:
        if lesson.get(key): body += '<section><h2>' + title + '</h2>' + ul(lesson[key]) + '</section>'
    if lesson.get('limits'): body += '<div class="callout"><strong>Scope of this diagram</strong><p>' + esc(lesson['limits']) + '</p></div>'
    body += '<section><h2>Work with the converted example</h2><ol><li>Open the viewer and select <code>' + esc(lesson['view']) + '</code>. Inspect the rendered view and its source.</li><li>Open the designer. Keep the selected profile and inspect its legal palette and property controls.</li><li>Change one displayed title or an appropriate data value. Check the live update in the resulting diagram.</li><li>Run the verifier and review its diagnostics before moving complete content into review.</li><li>Download your edited DDN source to retain the change.</li></ol><p>The example uses the indentation-based <code>ddn-next-1</code> dialect. <a href="../language.html">The language guide</a> explains reusable definitions, dotted data rows and explicit property blocks.</p></section>'
    if lesson.get('variants'):
        body += '<section><h2>Other views in this example</h2><ul>' + ''.join(f'<li><a href="{tool(lesson["entry"], v["view"], "view", "../../")}">{esc(v.get("title",v["view"]))}</a></li>' for v in lesson['variants']) + '</ul></section>'
    refs = [r for r in lesson.get('refs', []) if isinstance(r, str) and r.startswith(('https://','http://'))]
    if refs: body += '<section><h2>Further reading</h2><ul>' + ''.join(f'<li><a href="{esc(r)}">{esc(r)}</a></li>' for r in refs) + '</ul></section>'
    body += '<nav class="lesson-nav" aria-label="Adjacent lessons">'
    if index: body += f'<a href="{lessons[index-1]["id"]}.html">← {esc(lessons[index-1]["title"])}</a>'
    if index + 1 < len(lessons): body += f'<a href="{lessons[index+1]["id"]}.html">{esc(lessons[index+1]["title"])} →</a>'
    body += '</nav>'
    page('guide/lessons/' + lesson['id'] + '.html', lesson['title'], body, active='Guide')

page('reference/index.html', 'Reference', heading('The vocabulary, rules and defaults.', 'Use the adopted codex to see what a profile permits and what a property means. The reference is local to this website.', 'Reference') + '<div class="grid">' + card('profiles.html','151 profile contracts','Palettes, relationship endpoints, validation rules and profile defaults.') + card('roles.html','Element and relation roles','Meaning, semantic core type and reverse usage across profiles.') + card('properties.html','Property and default codex','Search property ownership, omission rules and CSS eligibility.') + card('../guide/language.html','Source spelling','How to express views, definitions, data and properties in the new dialect.') + '</div><section><h2>Read the rules in context</h2><p>The profile selects a method and projection. Its legal palette and endpoint contracts determine which items and relationships belong in a view. Presentation defaults are scoped by profile; a similar-looking shape does not make two roles interchangeable.</p><p>Draft material may be incomplete. A completed review applies the same identity, data and semantic rules used by the viewer and designer.</p></section>', active='Reference')

profile_index = heading('Every profile has a contract.', 'Choose a profile to inspect its palette, legal relationships, validation rules and default settings.', '151 profiles') + '<div class="search-controls"><label class="grow" for="profile-search">Search profiles<input type="search" id="profile-search" data-filter="profile-list" data-count="profile-count" placeholder="Try UML, ERD, timeline or chart"></label></div><p id="profile-count" class="count" aria-live="polite">151 profiles</p><div id="profile-list" class="grid">'
for identifier, spec in sorted(profiles.items()):
    profile_index += '<div data-search="' + esc(identifier + ' ' + spec.get('scope','') + ' ' + ' '.join(spec.get('diagram_families', []))) + '">' + card('profiles/' + slug(identifier) + '.html', esc(identifier), esc(spec.get('scope','')), esc(spec['projection']) + ' projection') + '</div>'
profile_index += '</div>'
page('reference/profiles.html','Profile contracts',profile_index,active='Reference')
for identifier, spec in sorted(profiles.items()):
    body = '<p class="breadcrumbs"><a href="../index.html">Reference</a> / <a href="../profiles.html">Profiles</a></p>' + heading(esc(identifier), esc(spec.get('scope','')), 'Profile contract')
    body += '<div class="fact-row"><span class="pill">' + esc(spec['projection']) + ' projection</span><span class="pill">' + esc(' · '.join(spec.get('diagram_families',[]))) + '</span></div><p><a class="cta light" href="../../gallery/index.html#profile-' + slug(identifier) + '">Open this profile in the gallery</a></p>'
    body += '<section><h2>Primary palette</h2>' + code_links(spec.get('primary_palette',[]),'../roles/') + '</section>'
    if spec.get('context_roles'): body += '<details><summary>Additional context roles</summary>' + code_links(spec['context_roles'],'../roles/') + '</details>'
    if spec.get('relation_roles'): body += '<section><h2>Relationship roles</h2>' + code_links(spec['relation_roles'],'../roles/','relation') + '</section>'
    if spec.get('relation_endpoint_contracts'):
        body += '<details><summary>Legal endpoints</summary><div class="table-scroll"><table><thead><tr><th>Relation</th><th>Source roles</th><th>Target roles</th><th>Self relation</th></tr></thead><tbody>'
        for row in spec['relation_endpoint_contracts']:
            body += '<tr><td><code>' + esc(row['role']) + '</code></td><td>' + esc(', '.join(row.get('source_roles',[]))) + '</td><td>' + esc(', '.join(row.get('target_roles',[]))) + '</td><td>' + ('Allowed' if row.get('self_allowed') else 'Not allowed') + '</td></tr>'
        body += '</tbody></table></div></details>'
    if spec.get('profile_rules'): body += '<section><h2>Profile verification</h2>' + ul(spec['profile_rules']) + '</section>'
    body += '<section><h2>Profile defaults</h2><p>Explicit file settings override eligible CSS, then these profile defaults and the common standard apply. Unspecified semantic facts remain unspecified.</p>' + code(json.dumps(spec.get('standard_overrides',{}),indent=2,ensure_ascii=False)) + '</section>'
    if spec.get('permitted_projection_properties'): body += '<section><h2>Projection properties</h2><p><code>' + esc(', '.join(spec['permitted_projection_properties'])) + '</code></p><p><a href="../properties.html?q=' + esc(identifier) + '">Search the property codex</a></p></section>'
    if spec.get('designer_commands'): body += '<section><h2>Design operations</h2>' + ul(spec['designer_commands']) + '</section>'
    if spec.get('bounded_analysis'): body += '<div class="callout"><strong>Bounded analysis</strong><p>' + esc(spec['bounded_analysis']) + '</p></div>'
    if spec.get('baseline_declared_exclusions'): body += '<section><h2>Outside this profile</h2>' + ul(spec['baseline_declared_exclusions']) + '</section>'
    page('reference/profiles/' + slug(identifier) + '.html',identifier,body,active='Reference')

compact_roles = []
for identifier, spec in sorted(roles.items()):
    contract = spec.get('contract',{})
    standard = spec.get('standard',{})
    compact = {'role':spec['role'],'slug':slug(identifier),'preview':'assets/symbols/' + slug(identifier) + '.svg','category':spec['category'],'name':contract.get('name',spec['role']),'meaning':contract.get('meaning',contract.get('meaning_and_direction','')),'code':contract.get('code',''),'colour':standard.get('colour',contract.get('colour','#334155')),'fill':standard.get('fill',contract.get('fill','#f1f5f9')),'family':contract.get('family',''),'profiles':sorted(role_usage[identifier])}
    compact_roles.append(compact)
    body = '<p class="breadcrumbs"><a href="../index.html">Reference</a> / <a href="../roles.html">Roles</a></p>' + heading(esc(compact['name']),esc('Recorded core meaning: ' + compact['meaning']),'Element role' if spec['category']=='element' else 'Relation role') + '<p><code>' + esc(spec['role']) + '</code></p><dl><dt>Category</dt><dd>' + esc(spec['category']) + '</dd><dt>Core binding</dt><dd>' + esc(spec.get('core', spec.get('pattern',''))) + '</dd><dt>Semantic family</dt><dd>' + esc(compact['family'] or 'See its profile') + '</dd></dl>'
    body += '<figure class="role-preview"><img src="../../' + compact['preview'] + '" alt="' + esc(spec['role']) + ' base contour"><figcaption>Base contour or default endpoint marks from the new renderer. Instance metadata, compartments and optional artwork add context in the full profile.</figcaption></figure>'
    if spec['category']=='element': body += '<section><h2>Declare this role</h2>' + code('element Example as ' + spec['role']) + '<p>Place the definition in a view whose profile permits this role. Reuse a shared definition with <code>use Example</code>.</p></section>'
    else: body += '<section><h2>Connect with this role</h2>' + code('connect Source to Target as ' + spec['role']) + '<p>Source and Target must already exist and satisfy the selected profile’s endpoint contract. Use the relation’s qualifiers for explicit semantic details.</p></section>'
    body += '<section><h2>Available in these profiles</h2>' + code_links(compact['profiles'],'../profiles/') + '</section>'
    if standard: body += '<details><summary>Standard presentation values</summary>' + code(json.dumps(standard,indent=2,ensure_ascii=False)) + '</details>'
    if spec.get('metadata'): body += '<details><summary>Registered metadata fields</summary><p><code>' + esc(', '.join(sorted(spec['metadata']))) + '</code></p></details>'
    body += '<p><a href="../properties.html?q=' + esc(identifier) + '">Search properties for this role</a></p>'
    page('reference/roles/' + slug(identifier) + '.html',identifier,body,active='Reference')

for path, title, mode, intro, active in [('reference/roles.html','Element and relation roles','roles','Look up a role’s meaning and the profiles that admit it. Previews show base contours and default endpoint marks from the current renderer; full profile examples add their contextual detail.','Reference'),('icons/index.html','Symbols and icon roles','roles','DDN symbols identify semantic roles. Explore base contours from the new renderer, then open a profile for instance-specific symbols, compartments and connectors.','Icons'),('reference/properties.html','Properties and defaults','properties','Search the adopted property codex by owner, path, role or profile. File settings override eligible CSS, which overrides the fixed standard default.','Reference')]:
    body = heading(title,intro,'Reference catalogue') + '<div class="search-controls"><label class="grow" for="reference-search">Search ' + ('properties' if mode=='properties' else 'roles') + '<input type="search" id="reference-search" placeholder="Name, meaning, owner or profile"></label><label for="reference-kind">' + ('Owner' if mode=='properties' else 'Category') + '<select id="reference-kind"><option value="">All</option></select></label></div><p id="reference-count" class="count" aria-live="polite"></p><div id="reference-results" data-mode="' + mode + '"></div><noscript><p>This search needs JavaScript. <a href="' + ('../reference/' if active=='Icons' else '') + 'profiles.html">Browse the static profile contracts</a> for palettes, rules and defaults.</p></noscript>'
    if active == 'Icons':
        body = body.replace('<div class="search-controls">', '<p><a class="cta light" href="art.html">Browse the example icon and illustration packs</a></p><div class="search-controls">', 1)
    page(path,title,body,active=active,scripts=('assets/reference-data.js','assets/reference.js'))

art_manifest_path = SITE / 'assets/icons/manifest.json'
if art_manifest_path.exists():
    artwork = json.loads(art_manifest_path.read_text())
    art_body = heading('Presentation artwork, with provenance.', 'The converted examples retain their referenced icon and illustration assets. The underlying DDN role and connection rules remain separate from the artwork.', 'Icon and art packs') + '<p><a href="index.html">Semantic role contours</a> · <a href="../assets/icons/manifest.json">Artwork manifest and attribution</a></p><div class="search-controls"><label class="grow" for="art-search">Search artwork<input type="search" id="art-search" data-filter="art-list" data-count="art-count" placeholder="Try electrical, pump, server or database"></label></div><p class="count" id="art-count" aria-live="polite">' + str(len(artwork['icons'])) + ' referenced assets</p><div id="art-list">'
    for library, metadata in artwork['libraries'].items():
        art_body += '<section data-filter-section><h2>' + esc(metadata['name']) + '</h2><p class="muted">' + esc(metadata['attribution']) + ' · <a href="../' + esc(metadata['notice']) + '">Original notice</a></p><div class="grid">'
        for key, item in artwork['icons'].items():
            if item['library'] != library: continue
            art_body += '<article class="card art-card" data-search="' + esc(key + ' ' + item['name'] + ' ' + ' '.join(item.get('tags',[]))) + '"><img loading="lazy" src="../' + esc(item['path']) + '" alt="' + esc(item['name']) + '"><h3>' + esc(item['name']) + '</h3><p class="source-name"><code>' + esc(key) + '</code></p><p><span class="pill">' + esc(item['license']) + '</span></p><details><summary>Examples and provenance</summary><ul>'
            for entry in item['examples']:
                art_body += '<li><a href="' + tool(entry,'','view') + '">' + esc(Path(entry).stem) + '</a></li>'
            art_body += '</ul>'
            if item.get('provenance'):
                art_body += '<p>' + esc(item['provenance'].get('author','')) + '</p>'
                url = item['provenance'].get('source','')
                if url.startswith(('https://','http://')): art_body += '<p><a href="' + esc(url) + '">Original artwork source</a></p>'
            art_body += '</details></article>'
        art_body += '</div></section>'
    art_body += '</div><p>DDN and its original artwork are open source under GPLv2 or later. Third-party artwork retains the individual licences and attribution listed above. See <a href="../license/index.html">licensing and sponsorship</a>.</p>'
    page('icons/art.html','Example artwork packs',art_body,active='Icons')

compact_properties = [{key:prop.get(key) for key in ['id','owner','path','meaning','default','css']} for prop in properties['properties']]
(SITE/'assets/reference-data.js').write_text('/* Generated from the adopted ddn-next-1 codex. */\nwindow.DDN_WEBSITE_REFERENCE=' + json.dumps({'version':'ddn-next-1','roles':compact_roles,'properties':compact_properties},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c') + ';\n')

page('docs/index.html','Documentation',heading('Build with the DDN utilities.','The model, language and rule modules are independent of the browser. DOM adapters provide viewing and editing; the host supplies IO and authority.','Developer guide') + '<div class="grid">' + card('embedding.html','Embed a viewer','Create a complete runtime, open source files and mount the read-only browser adapter.') + card('modular.html','Load only the required tools','Offline packs, shared modules and automatic diagram-family loading.') + card('architecture.html','Module responsibilities','How parser, model, profiles, defaults, runtime, presentation and utility adapters fit together.') + card('../guide/language.html','Author the source','Use the adopted dialect and property codex rather than the deprecated prototype language.') + card('../download/index.html','Local distributions','Open complete HTML utilities directly from disk or embed the shared module tree.') + '</div><section><h2>Choose the API for the responsibility</h2><p>The viewer observes and captures. The designer applies authorized commands through the shared runtime. The verifier checks the selected scope and reports completeness and unsupported capabilities explicitly. Source parsing does not execute arbitrary scripts or fetch missing dependencies.</p></section>',active='Docs')

page('docs/embedding.html','Embedding',heading('Embed the complete viewer.','Use the shared module directory with the complete profile pack. ESM loading follows the host’s normal browser policy; the HTML utilities also open directly from disk.','Developer guide') + code("import { createRuntime, createCompleteRuntimeOptions, createViewer }\n    from './download/ddn-viewer.js';\n\nconst runtime = createRuntime(createCompleteRuntimeOptions());\nconst viewer = createViewer(document.querySelector('#diagram'), { runtime });\nawait viewer.open({\n    entry: 'main.ddn',\n    files: [{\n        id: 'main.ddn',\n        text: 'erd Sales\\n    Customer\\n    Order\\n    connect Customer to Order\\n',\n        revision: '1', encoding: 'utf-8', writable: true,\n    }],\n});\n\n// When the host removes the view:\nviewer.destroy();\nruntime.destroy();") + '''<section><h2>Add editing deliberately</h2><p><code>createDesigner(viewer, { authority })</code> adds editing controls to an existing viewer. The authority provider decides the distinct grants for model edits, lifecycle review, acceptance and reopening. Prepared changes recheck authority and revisions before commit.</p><p>A viewer receiving a supplied update remains read-only. The host calls <code>runtime.ingest()</code> with identified provider data and a matching base revision; displaying it does not grant participation rights.</p></section><section><h2>Use the verifier independently</h2><p>The verifier module exports <code>createVerifier</code>, <code>createCompletePack</code> and <code>createCompleteRuntimeOptions</code>. The same profile rules are used by the viewer and designer. Inspect complete, partial and unsupported results instead of treating the absence of a thrown error as acceptance.</p></section><section><h2>Keep the files together</h2><p>Distribute the JavaScript facades with their shared <code>modules/</code> directory. Supply the document’s included source files, stylesheets and local assets explicitly. A missing file remains an unresolved dependency until the host supplies it.</p><p><a href="../download/index.html">Download the complete tools</a></p></section>''',active='Docs')

page('docs/architecture.html','Architecture',heading('One model and shared rules.','Small modules separate semantic work from rendering, editing, IO and optional services.','Architecture') + '''<div class="table-scroll"><table><thead><tr><th>Modules</th><th>Responsibility</th></tr></thead><tbody><tr><td>types</td><td>Core, scene and browser API contracts.</td></tr><tr><td>model, language</td><td>Qualified identities, indentation parsing, typed records and source patches.</td></tr><tr><td>profiles, defaults</td><td>Codex, profile rules and file &gt; CSS &gt; standard resolution.</td></tr><tr><td>execution</td><td>Fingerprints, budgets, cancellation and optional worker execution.</td></tr><tr><td>runtime</td><td>Immutable revisions, data providers, commands, lifecycle protection and history.</td></tr><tr><td>presentation, viewer</td><td>Profile scenes, tables, safe Markdown, navigation, inspection and capture.</td></tr><tr><td>designer</td><td>Editing controls using the shared viewer and command service.</td></tr><tr><td>verifier, standalone</td><td>Staged verification and local browser application shells.</td></tr></tbody></table></div><section><h2>Versioned identity and updates</h2><p>Definitions carry stable identity separate from the displayed label. Files retain their identity when included in a main workarea. Commands and data revisions check their base state so a stale operation cannot quietly overwrite newer work.</p></section><section><h2>Boundary with Weaver</h2><p>The DDN foundation is a standalone single-user client system. Commercial coordination, multi-user collaboration, meetings, media and server paging are Weaver responsibilities. None is required to open or edit a local DDN diagram.</p></section><section><h2>Scope and qualification</h2><p>The complete edition implements the adopted bounded profiles. Full standards execution and external certification are not implied. Browser, accessibility, performance and release qualification remain separate from the presence of a profile in the registry.</p></section>''',active='Docs')

page('standard/index.html','The DDN standard',heading('A small language. Explicit contracts.','The adopted ddn-next-1 language and codex define source spelling, data, defaults and rules independently of any one application.','Standard') + '<div class="grid">' + card('../guide/language.html','Language reference','Declarations, indentation, table cells, quotes, notes, files and status.') + card('../reference/properties.html','Property and default codex','Every property’s ownership, meaning, omission rule and CSS eligibility.') + card('../reference/profiles.html','Profile contracts','All 151 method-specific palettes, connections, projections and bounded rules.') + card('../reference/roles.html','Elements and relations','Roles and semantic meanings connected to their permitted profiles.') + card('../docs/architecture.html','Utility architecture','Viewer, designer, verifier and shared runtime responsibilities.') + card('../guide/quick-start.html','Readable authoring','Minimal examples with progressive detail.') + '</div><section><h2>How the contracts fit together</h2><ol><li>A file declares one workarea and contains views, documents, definitions and data.</li><li>The selected profile supplies method-specific rules and defaults.</li><li>Elements and relations retain identity independently of appearances.</li><li>Explicit file settings override eligible type-scoped CSS, then versioned standards.</li><li>Verification reports logical consistency and completeness for the requested scope.</li></ol></section><section><h2>Version and release status</h2><p><code>ddn-next-1</code> is the current implementation contract identifier. It is distinct from the deprecated prototype dialect. A change to standard defaults requires a new version; software upgrades do not silently alter an existing file’s defaults.</p><p>DDN is an open-source project and open standard proposal, sponsored by <a href="https://scratchbird.ca">ScratchBird Software Inc.</a> The language documentation, examples and tools are available under <a href="../license/index.html">GPLv2 or later</a>.</p></section>',active='Standard')

page('download/index.html','Download',heading('Choose how to run DDN.','Free, open-source viewer, designer and verifier under GPLv2 or later. Choose modular tools or complete single-file utilities, with all 151 adopted profiles supported.','Download') + '<section><h2>Modular tools</h2><p>Open <a href="modular/viewer.html">Viewer</a>, <a href="modular/designer.html">Designer</a> or <a href="modular/verifier.html">Verifier</a>. For offline use, <a href="ddn-modular.zip" download>download the complete folder as a ZIP</a>, extract it and open the appropriate HTML file. Keep its chunks and resource files together.</p><p><a href="../docs/modular.html">Modular embedding and deployment</a></p></section><section><h2>Complete single-file utilities</h2></section><div class="grid">' + card('ddn-viewer.html','DDN viewer','Read-only viewing, navigation, source inspection and supported snapshot capture.') + card('ddn-visual-designer.html','DDN visual designer','The viewer plus authorized visual and source editing, history and lifecycle actions.') + card('ddn-verifier.html','DDN verifier','Independent source, property, reference and semantic diagnostics.') + '</div><section><h2>JavaScript modules</h2><p>For embedding, use these facades together with the shared <code>modules/</code> directory. Downloading only a facade does not include its dependencies.</p><ul><li><a href="ddn-viewer.js" download>ddn-viewer.js</a></li><li><a href="ddn-visual-designer.js" download>ddn-visual-designer.js</a></li><li><a href="ddn-verifier.js" download>ddn-verifier.js</a></li></ul><p><a href="../docs/embedding.html">Embedding instructions</a> · <a href="../gallery/index.html">Converted example sources</a></p></section><section><h2>Saving your work</h2><p>The designer returns edited source for download. The browser’s download action controls where it is stored. Opening the viewer or verifier does not alter your original file.</p><p>DDN is free for general public use under <a href="../license/index.html">GPLv2 or later</a>. No Weaver subscription is required. Keep the <a href="LICENSE">licence text</a>, <a href="NOTICE.md">notices</a> and third-party resource licences with redistributed copies. Visit the <a href="https://github.com/scratchbird-software-inc/Diagram-Design-Notation">public DDN project</a> for source and contributions.</p></section>',active='Download')

